import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Finds the shortest path and distance from start to end in a weighted directed graph using Dijkstra's algorithm."""

    # Priority queue for the Dijkstra's algorithm
    priority_queue = []
    heapq.heappush(priority_queue, (0, start))

    # Distance dictionary to keep track of the shortest distance to each node
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    # Parent dictionary to reconstruct the shortest path
    parents = {start: None}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_node == end:
            break

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                parents[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    if distances[end] == float('inf'):
        return (float('inf'), [])

    # Reconstruct the path
    path = []
    while end is not None:
        path.append(end)
        end = parents[end]
    path.reverse()

    return (distances[path[0]], path)
